export function OgLogo({ height = 48 }: { height?: number }) {
	return (
		<div
			style={{
				display: "flex",
				alignItems: "center",
				gap: `${Math.round(height * 0.3)}px`,
			}}
		>
			<OgLogomark height={height} />
			<OgWordmark height={Math.round(height * 0.62)} />
		</div>
	);
}
